const cfg = $('Config').first().json;
const buf = Buffer.from(String(cfg.file_base64), 'base64');
const bin = await this.helpers.prepareBinaryData(buf, cfg.file_name || 'file', cfg.file_mime || undefined);
return [{ json: { source: 'base64' }, binary: { data: bin } }];

const raw = $input.first().json;
let text = '';
if (typeof raw.content === 'string') text = raw.content;
else if (Array.isArray(raw.content)) text = raw.content.map(function (c) { return c.text || ''; }).join('\n');
else if (typeof raw.text === 'string') text = raw.text;
else if (typeof raw.output === 'string') text = raw.output;
else text = JSON.stringify(raw);
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
const fileId = $('Config').first().json.file_id;
try {
  const data = JSON.parse(start >= 0 && end > start ? text.slice(start, end + 1) : text);
  return [{ json: { ok: true, file_id: fileId, result: data } }];
} catch (e) {
  return [{ json: { ok: false, file_id: fileId, error: 'Could not parse the model response as JSON.', raw_response: text.slice(0, 2000) } }];
}

const cfg = $('Config').first().json;
function parse(v, fallback) {
  if (v === undefined || v === null || v === '') return fallback;
  if (typeof v === 'object') return v;
  try { return JSON.parse(v); } catch (e) { return fallback; }
}
function esc(s) { return String(s || '').replace(/'/g, "\\'"); }
const receipt = parse(cfg.receipt_json, {});
let items = parse(cfg.items_json, []);
if (!Array.isArray(items)) items = items.items || [];
items = items.filter(function (p) { return p && p.has_warranty !== false; });
if (!cfg.file_id && !cfg.file_base64) return [{ json: { error: 'Missing file_id of the receipt.' } }];
if (!receipt.purchase_date) return [{ json: { error: 'Missing purchase_date in receipt_json.' } }];
if (items.length === 0) return [{ json: { error: 'No items with warranty to save.' } }];
const formula = receipt.receipt_number
  ? "AND({Store}='" + esc(receipt.store) + "',{Receipt number}='" + esc(receipt.receipt_number) + "',IS_SAME({Purchase date},'" + esc(receipt.purchase_date) + "','day'))"
  : 'FALSE()';
const receiptBody = {
  typecast: true,
  records: [{ fields: {
    'Store': receipt.store || '',
    'Store type': receipt.store_type || 'unknown',
    'Purchase date': receipt.purchase_date,
    'Receipt number': receipt.receipt_number || '',
    'Total': Number(receipt.total) || 0,
    'Currency': receipt.currency || '',
    'Telegram file ID': cfg.file_id || ''
  } }]
};
return [{ json: { receipt: receipt, items: items, formula: formula, receipt_body: receiptBody, force: cfg.force === true || cfg.force === 'true' }, binary: $input.first().binary }];

const item = $input.first();
const bin = (item.binary || {}).data;
if (!bin) throw new Error('The receipt file could not be downloaded.');
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
if (buf.length > 5 * 1024 * 1024) throw new Error('The file is larger than 5 MB, which Airtable does not accept. Please send a smaller file or a photo.');
const name = bin.fileName || (bin.mimeType === 'application/pdf' ? 'receipt.pdf' : 'receipt.jpg');
return [{ json: { contentType: bin.mimeType || 'application/octet-stream', filename: name, file: buf.toString('base64') } }];

const data = $('Prepare purchase').first().json;
const cfg = $('Config').first().json;
const receiptId = $('Create receipt').first().json.records[0].id;
const r = data.receipt;
const sources = { receipt: 'Receipt', statutory_default: 'Statutory (default)', uncertain: 'To verify' };
const records = data.items.map(function (p) {
  return { fields: {
    'Name': p.name || p.name_on_receipt || 'Unnamed',
    'Name on receipt': p.name_on_receipt || '',
    'Manufacturer': p.manufacturer || '',
    'Model': p.model || '',
    'Category': p.category || 'other',
    'Price': Number(p.price) || 0,
    'Quantity': Number(p.quantity) || 1,
    'Store': r.store || '',
    'Purchase date': r.purchase_date,
    'Warranty (months)': Number(p.warranty_months) || Number(cfg.default_warranty_months) || 24,
    'Warranty source': sources[p.warranty_source] || 'Statutory (default)',
    'Status': 'Active',
    'Needs photo': p.needs_photo === true,
    'Note': p.note || '',
    'Receipt': [receiptId]
  } };
});
const out = [];
for (let i = 0; i < records.length; i += 10) {
  out.push({ json: { body: { typecast: true, records: records.slice(i, i + 10) } } });
}
return out;

const products = [];
for (const item of $input.all()) {
  for (const r of (item.json.records || [])) {
    products.push({ product_id: r.id, name: r.fields['Name'], warranty_until: r.fields['Warranty until'] || null, needs_photo: r.fields['Needs photo'] === true });
  }
}
return [{ json: { ok: true, receipt_id: $('Create receipt').first().json.records[0].id, saved_products: products.length, products: products } }];

const cfg = $('Config').first().json;
if (!cfg.product_id) throw new Error('Missing product_id.');
const item = $input.first();
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
return [{ json: { product_id: cfg.product_id, contentType: 'image/jpeg', filename: 'product.jpg', file: buf.toString('base64') }, binary: item.binary }];

const raw = $input.first().json;
let text = '';
if (typeof raw.content === 'string') text = raw.content;
else if (Array.isArray(raw.content)) text = raw.content.map(function (c) { return c.text || ''; }).join(' ');
else text = raw.text || raw.output || '';
return [{ json: { description: text.trim() } }];

const query = String($('Config').first().json.query || '').trim().toLowerCase();
const words = query.split(' ').filter(function (s) { return s.length > 1; }).map(function (s) { return s.replace(/'/g, ''); });
const fields = "LOWER(CONCATENATE({Name},' ',{Name on receipt},' ',{Manufacturer},' ',{Model},' ',{Category},' ',{Store},' ',{Description}))";
const formula = words.length === 0 ? '' : 'AND(' + words.map(function (s) { return "SEARCH('" + s + "'," + fields + ')'; }).join(',') + ')';
return [{ json: { formula: formula } }];

const records = $input.first().json.records || [];
const products = records.slice(0, 50).map(function (r) {
  const f = r.fields || {};
  return {
    product_id: r.id, name: f['Name'], manufacturer: f['Manufacturer'] || '', model: f['Model'] || '', category: f['Category'] || '',
    store: f['Store'] || '', purchase_date: f['Purchase date'], warranty_until: f['Warranty until'], days_left: f['Days left'],
    validity: f['Validity'], status: f['Status'], description: f['Description'] || '', has_photo: Array.isArray(f['Product photo']) && f['Product photo'].length > 0
  };
});
return [{ json: { ok: true, count: records.length, shown: products.length, products: products } }];

const days = String($('Config').first().json.reminder_days || '183,31,7').split(',').map(function (s) { return Number(s.trim()); });
const flags = ['Notified 6m', 'Notified 1m', 'Notified 1w'];
const parts = days.slice(0, 3).map(function (d, i) { return 'AND({Days left}<=' + d + ',NOT({' + flags[i] + '}))'; });
const formula = "AND({Status}='Active',{Days left}>=0,OR(" + parts.join(',') + '))';
return [{ json: { formula: formula, days: days } }];

const days = $('Reminder formula').first().json.days;
const codes = ['6m', '1m', '1w'];
const labels = { '6m': '6 months', '1m': '1 month', '1w': '1 week' };
const records = $input.first().json.records || [];
const products = records.map(function (r) {
  const f = r.fields || {};
  const left = Number(f['Days left']);
  const reached = [];
  codes.forEach(function (k, i) { if (left <= days[i] && f['Notified ' + k] !== true) reached.push(k); });
  const nearest = reached.length ? reached[reached.length - 1] : null;
  return {
    product_id: r.id, name: f['Name'], manufacturer: f['Manufacturer'] || '', model: f['Model'] || '', category: f['Category'] || '',
    store: f['Store'] || '', purchase_date: f['Purchase date'], warranty_until: f['Warranty until'], days_left: left,
    reminder: nearest ? labels[nearest] : null, thresholds_to_mark: reached.join(',')
  };
});
return [{ json: { ok: true, count: products.length, products: products } }];

const cfg = $('Config').first().json;
if (!cfg.product_id) throw new Error('Missing product_id.');
const fields = {};
String(cfg.thresholds || '').split(',').map(function (s) { return s.trim(); }).forEach(function (k) {
  if (k === '6m' || k === '1m' || k === '1w') fields['Notified ' + k] = true;
});
const allowed = ['Active', 'Claimed', 'Retired'];
if (cfg.status && allowed.indexOf(cfg.status) >= 0) fields['Status'] = cfg.status;
if (Object.keys(fields).length === 0) throw new Error('Nothing to save: provide thresholds (6m,1m,1w) or a status.');
return [{ json: { body: { typecast: true, records: [{ id: cfg.product_id, fields: fields }] } } }];
